def chain_follow(chain):
    chain_dict = {}
    for token in chain:
        if token not in chain_dict:
            chain_dict[token] = []

    current = chain_dict[chain[0]]
    result = []

    while current:
        next_token = current.pop()
        result.append(next_token)

        if next_token in chain_dict:
            current = chain_dict[next_token]
        else:
            current = None

    return ','.join(result)

# Example usage:
# print(chain_follow((('ffh', 'fgh'), ('aa', 'bb'))))  # Output: 'ffh, fgh, aa, bb'
